import { signHs256 } from './hs256.mjs';

const HEADER = {
  alg: 'HS256',
  typ: 'JWT',
};

function splitToken(token) {
  const segments = token.split('.');

  if (segments.length !== 3) {
    throw new Error('Not enough segments');
  }

  return segments;
}

export async function encodeJwt(payload, secret) {
  const signingInput = [
    encodeJsonAsBase64Url(HEADER),
    encodeJsonAsBase64Url(payload),
  ].join('.');
  const signature = await signHs256(signingInput, secret);

  return `${signingInput}.${signature}`;
}

